// Generated by Manus asset storage.
// Local filesystem, asset validation and export primitives shared by project commands and platform preparation.


import {
  closeSync,
  constants,
  cpSync,
  existsSync,
  fchmodSync,
  fstatSync,
  lstatSync,
  mkdirSync,
  openSync,
  readFileSync,
  realpathSync,
  readSync,
  readdirSync,
  renameSync,
  rmSync,
  rmdirSync,
  statSync,
  writeFileSync,
} from 'node:fs'

import { join, relative, resolve, sep } from 'node:path'
import { readAssetUploadJournal } from './asset-upload-journal.mjs'




const LARGE = ['index.wasm', 'index.pck']

const EXPORT_OUTPUTS = ['index.html', 'index.js', ...LARGE]

const STATE_FILE = '.manus-artifacts.json'

const EXPORT_LOCK_FILE = join('dist', '.export-lock')

const SKIP_DIRS = new Set([
  '.git',
  'node_modules',
  'dist',
  'site',
  '.godot',
  '.manus',
  '.manus-webdev',
  '.manus-logs',
  'test-output',
  'game-captures',
])



function ensureDistDirectory(root = process.cwd()) {
  const realRoot = realpathSync(root)
  const dist = join(realRoot, 'dist')
  if (existsSync(dist)) {
    const info = lstatSync(dist)
    if (!info.isDirectory() || info.isSymbolicLink() || realpathSync(dist) !== dist) {
      throw new Error('dist must be a project directory')
    }
  } else {
    mkdirSync(dist, { recursive: true })
  }
  return dist
}


function validateExportDirectory(root, directory, required = EXPORT_OUTPUTS) {
  const dist = ensureDistDirectory(root)
  const expected = resolve(directory)
  const rel = relative(dist, expected)
  if (!rel || rel.startsWith('..') || rel.split(sep).includes('..')) {
    throw new Error('export staging must be inside dist')
  }
  if (!existsSync(expected) || lstatSync(expected).isSymbolicLink() || realpathSync(expected) !== expected) {
    throw new Error('export staging must be a project directory')
  }
  const walk = (dir) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const path = join(dir, entry.name)
      const info = lstatSync(path)
      if (info.isSymbolicLink()) throw new Error(`export output cannot be a symbolic link: ${entry.name}`)
      if (info.isDirectory()) walk(path)
      else if (!info.isFile()) throw new Error(`invalid export output: ${entry.name}`)
    }
  }
  walk(expected)
  for (const file of required) {
    const output = join(expected, file)
    if (!existsSync(output) || !lstatSync(output).isFile() || statSync(output).size === 0) {
      throw Object.assign(new Error(`export incomplete: ${file} missing or empty`), { code: 'GAME_EXPORT_ARTIFACT_MISSING' })
    }
    if (file === 'index.wasm' || file === 'index.pck') {
      const header = Buffer.alloc(4)
      const fd = openSync(output, 'r')
      try { readSync(fd, header, 0, 4, 0) } finally { closeSync(fd) }
      const magic = file === 'index.wasm' ? Buffer.from([0, 97, 115, 109]) : Buffer.from('GDPC')
      if (!header.equals(magic)) throw new Error(`export invalid: ${file} header`)
    }
  }
  return expected
}





function readExportLock(root) {
  try {
    const lockPath = join(root, EXPORT_LOCK_FILE)
    const info = lstatSync(lockPath)
    // A creator may not have written its PID yet. Unknown ownership is busy,
    // never evidence that another process can remove the lock.
    if (!info.isFile() || info.isSymbolicLink() || info.size > 32) return { pid: -1, dead: false }
    const pid = Number(readFileSync(lockPath, 'utf8').trim())
    if (!Number.isSafeInteger(pid) || pid <= 0) return { pid: -1, dead: false }
    try {
      process.kill(pid, 0)
      return { pid, dead: false }
    } catch (error) {
      // Even a long export/upload retains ownership while its process lives.
      return { pid, dead: error.code === 'ESRCH' }
    }
  } catch (error) {
    return error.code === 'ENOENT' ? null : { pid: -1, dead: false }
  }
}


// Exclusive creation elects one exporter. Stale reclamation is serialized so
// two waiters cannot both remove the dead PID and then delete a new owner's lock.
function tryAcquireExportLock(root = process.cwd()) {
  const dist = ensureDistDirectory(root)
  const lockPath = join(dist, '.export-lock')
  const claim = () => {
    try {
      writeFileSync(lockPath, String(process.pid), { flag: 'wx' })
      return true
    } catch (error) {
      if (error.code !== 'EEXIST') throw error
      return false
    }
  }
  if (claim()) return true
  const reclaim = join(dist, '.export-lock-reclaim')
  try { mkdirSync(reclaim) } catch (error) {
    if (error.code !== 'EEXIST') throw error
    return false
  }
  try {
    // Reread only after winning reclamation; do not trust a pre-guard snapshot.
    const owner = readExportLock(root)
    if (owner && !owner.dead) return false
    if (owner) rmSync(lockPath)
    // If it was absent, another normal claimant may already have won; wx
    // handles that without deleting or replacing its newly created lock.
    return claim()
  } finally {
    // Do not recursively delete an unexpected guard. A crash in this short
    // reclamation window deliberately fails busy until the guard is cleared.
    rmdirSync(reclaim)
  }
}


function acquireExportLockSync(root = process.cwd(), { timeoutMs = 16 * 60_000 } = {}) {
  if (!Number.isFinite(timeoutMs) || timeoutMs < 0) throw new Error('Game build lock timeout is invalid')
  const deadline = performance.now() + timeoutMs
  let announced = false
  const signal = new Int32Array(new SharedArrayBuffer(4))
  for (;;) {
    if (tryAcquireExportLock(root)) return
    const remaining = deadline - performance.now()
    if (remaining <= 0) throw new Error('Game build is busy; timed out waiting for the current build to finish')
    if (!announced) {
      console.log('[export] waiting for in-flight Game build; checking inputs again after it finishes')
      announced = true
    }
    Atomics.wait(signal, 0, 0, Math.min(2000, remaining))
  }
}


function releaseExportLock(root = process.cwd()) {
  try {
    const pid = Number(readFileSync(join(root, EXPORT_LOCK_FILE), 'utf8').trim())
    if (pid === process.pid) rmSync(join(root, EXPORT_LOCK_FILE), { force: true })
  } catch {
    /* already gone */
  }
}


// Asset sync: binary assets never enter git. assets.lock.json (committed) maps
// each project-relative path to its storage location and content hash, and the
// tree is made whole from it before every export.

const ASSETS_LOCK_FILE = 'assets.lock.json'

const ASSETS_DIR = 'assets'

const MAX_ASSET_SIZE_BYTES = 512 * 1024 * 1024

const PUBLIC_ASSET_HOSTS = new Set([
  'files.manuscdn.com',
  'd1oupeiobkpcny.cloudfront.net',
])

const ASSET_TYPE_BY_EXT = new Map([
  ['.png', 'image'],
  ['.jpg', 'image'],
  ['.jpeg', 'image'],
  ['.webp', 'image'],
  ['.gif', 'image'],
  ['.bmp', 'image'],
  ['.svg', 'image'],
  ['.ico', 'image'],
  ['.ogg', 'audio'],
  ['.wav', 'audio'],
  ['.mp3', 'audio'],
  ['.m4a', 'audio'],
  ['.mp4', 'video'],
  ['.webm', 'video'],
  ['.ttf', 'font'],
  ['.otf', 'font'],
  ['.woff', 'font'],
  ['.woff2', 'font'],
  ['.ttc', 'font'],
  ['.otc', 'font'],
  ['.glb', 'model'],
  ['.gltf', 'model'],
  ['.obj', 'model'],
  ['.fbx', 'model'],
  ['.blend', 'model'],
  ['.dae', 'model'],
])

const ASSET_EXTS = new Set(ASSET_TYPE_BY_EXT.keys())

// Saved checkpoints contain model lock entries, while hydration keeps the bytes
// in the workspace. Ignore those bytes without hiding versioned dependencies.
function ensureManagedModelGitignore(root, manifest) {
  if (!Object.entries(manifest.assets).some(([path, entry]) => path.startsWith('assets/') && entry.assetType === 'model')) return
  const path = join(root, '.gitignore')
  if (existsSync(path) && (!lstatSync(path).isFile() || lstatSync(path).isSymbolicLink())) throw new Error('Game .gitignore must be a regular file')
  let current = '', mode, fd
  try {
    fd = openSync(path, constants.O_RDONLY | constants.O_NOFOLLOW)
    const info = fstatSync(fd)
    if (!info.isFile()) throw new Error('Game .gitignore must be a regular file')
    current = readFileSync(fd, 'utf8')
    mode = info.mode & 0o777
  } catch (error) {
    if (error.code !== 'ENOENT') throw error
  } finally { if (fd !== undefined) closeSync(fd) }
  const existing = new Set(current.split(/\r?\n/))
  const rules = [...ASSET_TYPE_BY_EXT].filter(([, type]) => type === 'model').map(([extension]) =>
    '/assets/**/*' + extension.replace(/[a-z]/g, letter => `[${letter}${letter.toUpperCase()}]`))
    .filter(rule => !existing.has(rule))
  if (!rules.length) return
  const content = current + (current && !current.endsWith('\n') ? '\n' : '') + '# Manifest-hydrated 3D models\n' + rules.join('\n') + '\n'
  const temporary = `${path}.tmp-${process.pid}`
  let owned = false
  try {
    const output = openSync(temporary, constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | constants.O_NOFOLLOW, mode ?? 0o666)
    owned = true
    try {
      if (mode !== undefined) fchmodSync(output, mode)
      writeFileSync(output, content)
    } finally { closeSync(output) }
    // Publish all rules together; a short write must not leave a broad partial glob.
    renameSync(temporary, path)
  } finally { if (owned) rmSync(temporary, { force: true }) }
}


function emptyAssetsManifest() {
  return { version: 2, groups: {}, bundles: {}, assets: {} }
}


function normalizeGroupId(value) {
  if (typeof value !== 'string') return ''
  return value
    .trim()
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, '-')
    .replace(/^-+|-+$/g, '')
}


function defaultGroupId(rel) {
  const parts = rel.split('/').slice(1, -1)
  if (parts[0] === 'template') return 'template'
  return normalizeGroupId(parts[0]) || 'ungrouped'
}


function defaultGroupName(groupId) {
  return groupId
    .split('-')
    .filter(Boolean)
    .map((part) => part[0].toUpperCase() + part.slice(1))
    .join(' ')
}


function assetTypeOf(rel) {
  return ASSET_TYPE_BY_EXT.get(extOf(rel)) || ''
}


function isManagedAssetRel(rel) {
  return (
    typeof rel === 'string' &&
    !rel.startsWith('/') &&
    !rel.includes('\\') &&
    !rel.split('/').some((part) => !part || part === '.' || part === '..') &&
    ASSET_EXTS.has(extOf(rel))
  )
}


function normalizeAssetEntry(rel, value, requireType = false) {
  if (!isManagedAssetRel(rel)) return null
  if (!value || typeof value !== 'object') return null
  const assetType = assetTypeOf(rel)
  if (requireType && value.assetType !== assetType) return null
  if (typeof value.path !== 'string' || !assetLocation(value.path)) return null
  if (requireType && (typeof value.sha256 !== 'string' || !/^sha256:[a-f0-9]{64}$/.test(value.sha256))) return null
  if (typeof value.sha256 === 'string' && value.sha256 && !/^sha256:[a-f0-9]{64}$/.test(value.sha256)) return null
  if (requireType && (!Number.isSafeInteger(value.size) || value.size <= 0)) return null
  if (typeof value.size === 'number' && (value.size < 0 ||
      (assetType === 'font' ? !Number.isSafeInteger(value.size) : value.size > MAX_ASSET_SIZE_BYTES))) return null
  const groupId = normalizeGroupId(value.groupId) || defaultGroupId(rel)
  const entry = {
    path: value.path,
    sha256: typeof value.sha256 === 'string' ? value.sha256 : '',
    size: typeof value.size === 'number' && value.size >= 0 ? value.size : 0,
    assetType,
    groupId,
  }
  if (typeof value.used === 'boolean') entry.used = value.used
  if (
    typeof value.alternateOf === 'string' &&
    value.alternateOf !== rel &&
    isManagedAssetRel(value.alternateOf)
  ) entry.alternateOf = value.alternateOf
  return entry
}


function normalizeAssetAlternates(manifest) {
  for (const [rel, entry] of Object.entries(manifest.assets)) {
    if (!entry.alternateOf) continue
    const primary = manifest.assets[entry.alternateOf]
    if (
      !primary ||
      primary.alternateOf ||
      primary.assetType !== entry.assetType ||
      primary.groupId !== entry.groupId ||
      extOf(entry.alternateOf) === extOf(rel)
    ) delete entry.alternateOf
  }
  return manifest
}


function normalizeGroups(value) {
  const groups = Object.create(null)
  if (!value || typeof value !== 'object') return groups
  for (const [id, group] of Object.entries(value)) {
    if (normalizeGroupId(id) !== id || !group || typeof group !== 'object') continue
    groups[id] = {
      name: typeof group.name === 'string' && group.name.trim() ? group.name.trim() : defaultGroupName(id),
      order: Number.isFinite(group.order) ? group.order : Object.keys(groups).length * 10 + 10,
    }
  }
  return groups
}


function normalizeBundleEntry(id, value, assets) {
  if (normalizeGroupId(id) !== id || !value || typeof value !== 'object') return null
  if (!Array.isArray(value.frames)) return null
  const frames = [...new Set(value.frames)].filter(
    (rel) => typeof rel === 'string' && assets[rel]?.assetType === 'image',
  )
  if (frames.length < 2) return null
  const first = assets[frames[0]]
  const fps = Number.isFinite(value.fps) ? Math.min(60, Math.max(1, value.fps)) : 12
  return {
    name: typeof value.name === 'string' && value.name.trim() ? value.name.trim() : defaultGroupName(id),
    assetType: 'animation',
    groupId: normalizeGroupId(value.groupId) || first.groupId,
    frames,
    fps,
    loop: value.loop !== false,
    coverFrame: frames.includes(value.coverFrame) ? value.coverFrame : frames[0],
    descriptor:
      typeof value.descriptor === 'string' && value.descriptor.startsWith(`${ASSETS_DIR}/`)
        ? value.descriptor
        : '',
  }
}


function ensureGroups(manifest) {
  for (const entry of Object.values(manifest.assets)) {
    if (!Object.hasOwn(manifest.groups, entry.groupId)) {
      manifest.groups[entry.groupId] = {
        name: defaultGroupName(entry.groupId),
        order: Object.keys(manifest.groups).length * 10 + 10,
      }
    }
  }
  return manifest
}


function readAssetsManifest(root = process.cwd()) {
  const lockPath = join(root, ASSETS_LOCK_FILE)
  try {
    const present = existsSync(lockPath)
    const content = present ? readFileSync(lockPath, 'utf8') : ''
    const parsed = present ? JSON.parse(content) : emptyAssetsManifest()
    if (!parsed || typeof parsed !== 'object') throw new Error(`${ASSETS_LOCK_FILE} must contain an object`)
    const isV2 = parsed.version === 2 && parsed.assets && typeof parsed.assets === 'object'
    const sourceAssets = isV2 ? parsed.assets : parsed
    const manifest = {
      version: 2,
      groups: normalizeGroups(isV2 ? parsed.groups : null),
      bundles: {},
      assets: {},
    }
    for (const [rel, value] of Object.entries(sourceAssets)) {
      const entry = normalizeAssetEntry(rel, value, isV2)
      if (!entry) throw new Error(`invalid asset entry: ${rel}`)
      manifest.assets[rel] = entry
    }
    for (const [rel, value] of readAssetUploadJournal(root, content)) {
      const entry = normalizeAssetEntry(rel, value, true)
      if (!entry) throw new Error(`invalid uploaded asset entry: ${rel}`)
      manifest.assets[rel] = entry
    }
    if (isV2 && parsed.bundles && typeof parsed.bundles === 'object') {
      for (const [id, value] of Object.entries(parsed.bundles)) {
        const bundle = normalizeBundleEntry(id, value, manifest.assets)
        if (bundle) manifest.bundles[id] = bundle
      }
    }
    return normalizeAssetAlternates(ensureGroups(manifest))
  } catch (error) {
    throw new Error(`invalid ${ASSETS_LOCK_FILE}: ${error?.message || error}`)
  }
}


function readAssetsLock(root = process.cwd()) {
  return readAssetsManifest(root).assets
}


function extOf(name) {
  const i = name.lastIndexOf('.')
  return i < 0 ? '' : name.slice(i).toLowerCase()
}


function directAssetUrl(entry) {
  if (typeof entry.path !== 'string') return ''
  try {
    const url = new URL(entry.path)
    if (url.protocol !== 'https:') return ''
    if (!PUBLIC_ASSET_HOSTS.has(url.hostname) && !url.hostname.endsWith('.files.manuscdn.com')) return ''
    return url.toString()
  } catch {
    return ''
  }
}


function projectStorageKey(path) {
  if (typeof path !== 'string' || !path.startsWith('/manus-storage/')) return ''
  const storageKey = path.slice('/manus-storage/'.length)
  if (!storageKey || storageKey.includes('\\')) return ''
  for (const part of storageKey.split('/')) {
    if (!part) return ''
    let decoded
    try {
      decoded = decodeURIComponent(part)
    } catch {
      return ''
    }
    if (!decoded || decoded === '.' || decoded === '..' || decoded.includes('/') || decoded.includes('\\')) return ''
  }
  return storageKey
}


function assetLocation(path) {
  return Boolean(directAssetUrl({ path }) || projectStorageKey(path))
}


function missingAssets(root = process.cwd()) {
  return absentEntries(root, readAssetsLock(root))
}


function isSafeAssetRel(root, rel) {
  if (!isManagedAssetRel(rel)) return false
  const target = resolve(root, rel)
  if (!target.startsWith(resolve(root) + sep)) return false
  let current = root
  for (const segment of rel.split('/')) {
    current = join(current, segment)
    try {
      if (lstatSync(current).isSymbolicLink()) return false
    } catch (err) {
      if (err.code !== 'ENOENT') throw err
    }
  }
  return true
}


function safeLockEntries(root, lock, log = console.log) {
  const keys = Object.keys(lock).filter((rel) => lock[rel] && typeof lock[rel] === 'object')
  const unsafe = keys.filter((rel) => !isSafeAssetRel(root, rel))
  for (const rel of unsafe) {
    log(`[assets] invalid asset path: ${rel}`)
  }
  if (unsafe.length) throw new Error(`invalid asset path in ${ASSETS_LOCK_FILE}: ${unsafe[0]}`)
  return keys
}


function absentEntries(root, lock) {
  return safeLockEntries(root, lock, () => {}).filter((rel) => !existsSync(join(root, rel)))
}


// A silent export would bake a pack with missing art and overwrite a good
// version with it.
function assertAssetsPresent(root = process.cwd()) {
  const missing = missingAssets(root)
  if (missing.length) {
    const shown = missing.slice(0, 5).join(', ')
    const more = missing.length > 5 ? ` (+${missing.length - 5} more)` : ''
    throw new Error(
      `refusing to export: ${missing.length} asset(s) recorded in ${ASSETS_LOCK_FILE} are missing locally: ${shown}${more}. Restore them through the project's supported asset synchronization or a complete source copy, then retry export.`,
    )
  }
}

export { LARGE, EXPORT_OUTPUTS, STATE_FILE, EXPORT_LOCK_FILE, SKIP_DIRS, ensureDistDirectory, validateExportDirectory, readExportLock, tryAcquireExportLock, acquireExportLockSync, releaseExportLock, ASSETS_LOCK_FILE, ASSETS_DIR, MAX_ASSET_SIZE_BYTES, PUBLIC_ASSET_HOSTS, ASSET_TYPE_BY_EXT, ASSET_EXTS, ensureManagedModelGitignore, emptyAssetsManifest, normalizeGroupId, defaultGroupId, defaultGroupName, assetTypeOf, isManagedAssetRel, normalizeAssetEntry, normalizeGroups, normalizeBundleEntry, ensureGroups, readAssetsManifest, readAssetsLock, extOf, directAssetUrl, projectStorageKey, assetLocation, missingAssets, isSafeAssetRel, safeLockEntries, absentEntries, assertAssetsPresent }
